def _get(name: str) -> List[float]:
    for n, v in EXPECTED:
        if n == name:
            return v
    raise ValueError("missing " + name)

def check(name: str, got, rtol: float = 1e-7, atol: float = 1e-10):
    want = _get(name)
    g = List[float]()
    for v in got:
        if isinstance(v, np.ndarray):
            for w in v.ravel():
                g.append(float(w))
        else:
            g.append(float(v))
    ok = len(g) == len(want)
    if ok:
        for i in range(len(want)):
            if abs(g[i] - want[i]) > atol + rtol * abs(want[i]):
                ok = False
    if not ok:
        print("TEST FAILED:", name, g, want)

def check_partition(name: str, got):
    # same clustering up to a relabeling (eigenvector order/sign freedom)
    want = _get(name)
    g = np.asarray(got).ravel()
    ok = g.size == len(want)
    if ok:
        fwd = Dict[int, int]()
        bwd = Dict[int, int]()
        for i in range(len(want)):
            a = int(g[i])
            b = int(want[i])
            if a in fwd and fwd[a] != b:
                ok = False
            if b in bwd and bwd[b] != a:
                ok = False
            fwd[a] = b
            bwd[b] = a
    if not ok:
        print("TEST FAILED:", name, g, want)

def cat3(a, b, c) -> List[float]:
    g = List[float]()
    for v in a.ravel():
        g.append(float(v))
    for v in b.ravel():
        g.append(float(v))
    for v in c.ravel():
        g.append(float(v))
    return g

rng = np.random.RandomState(0)
X = np.vstack([rng.randn(30, 2) * 0.4 + np.array([0., 0.]), rng.randn(30, 2) * 0.4 + np.array([4., 4.]),
               rng.randn(30, 2) * 0.4 + np.array([0., 5.]), rng.randn(20, 2) * 0.4 + np.array([-4., 2.])])
rb = np.random.RandomState(1)
B = rb.rand(24, 18) * 0.5
for i in range(8):
    for j in range(6):
        B[i, j] += 3.0
for i in range(8, 16):
    for j in range(6, 12):
        B[i, j] += 5.0
for i in range(16, 24):
    for j in range(12, 18):
        B[i, j] += 2.0
Q = np.array([[0.1, 0.2], [3.9, 4.2], [0.3, 4.6], [-3.0, 2.0]])

m = BisectingKMeans(n_clusters=4, random_state=0).fit(X)
check("bi_centers", m.cluster_centers_); check("bi_labels", m.labels_); check("bi_inertia", [m.inertia_]); check("bi_pred", m.predict(Q))
m = BisectingKMeans(n_clusters=5, random_state=2, bisecting_strategy="largest_cluster").fit(X)
check("bl_centers", m.cluster_centers_); check("bl_labels", m.labels_); check("bl_inertia", [m.inertia_]); check("bl_pred", m.predict(Q))
m = BisectingKMeans(n_clusters=4, random_state=3, init="k-means++", n_init=3).fit(X)
check("bk_centers", m.cluster_centers_); check("bk_labels", m.labels_); check("bk_inertia", [m.inertia_]); check("bk_pred", m.predict(Q))

c = SpectralCoclustering(n_clusters=3, random_state=0).fit(B)
check("co_rows", c.row_labels_); check("co_cols", c.column_labels_)
s = SpectralBiclustering(n_clusters=(3, 3), method="bistochastic", random_state=0, n_components=4, n_best=2).fit(B)
check("bc_bistochastic_rows", s.row_labels_); check("bc_bistochastic_cols", s.column_labels_)
s = SpectralBiclustering(n_clusters=(3, 3), method="log", random_state=0, n_components=4, n_best=2).fit(B)
check("bc_log_rows", s.row_labels_); check("bc_log_cols", s.column_labels_)
s = SpectralBiclustering(n_clusters=(3, 3), method="scale", random_state=0, n_components=4, n_best=2).fit(B)
check("bc_scale_rows", s.row_labels_); check("bc_scale_cols", s.column_labels_)

ce, la, inr = k_means(X, 4, random_state=0, n_init=3)
check("km_func", cat3(ce, la, np.array([inr])))
n = X.shape[0]
S = np.empty((n, n))
for i in range(n):
    for j in range(n):
        S[i, j] = -((X[i, 0] - X[j, 0]) ** 2 + (X[i, 1] - X[j, 1]) ** 2)
idx, lab, nit = affinity_propagation(S, random_state=0, return_n_iter=True)
check("ap_func", cat3(idx, lab, np.array([float(nit)])))
mc, ml = mean_shift(X, bandwidth=1.2)
check("ms_func", cat3(mc, ml, np.empty(0)))
A = np.exp(0.5 * S)
check_partition("sc_func", spectral_clustering(A, n_clusters=4, random_state=0, assign_labels="discretize"))
